function generateComposeConfig() {
    return {
        version: '3.8',
        services: {
            frontend: {
                image: 'nginx:alpine',
                ports: ['80:80'],
                depends_on: { backend: { condition: 'service_healthy' } },
                networks: ['app-network'],
                restart: 'unless-stopped',
                healthcheck: {
                    test: ['CMD', 'curl', '-f', 'http://localhost'],
                    interval: '30s', timeout: '10s', retries: 3, start_period: '10s'
                }
            },
            backend: {
                image: 'python:3.11',
                ports: ['8000:8000'],
                depends_on: {
                    db: { condition: 'service_healthy' },
                    redis: { condition: 'service_healthy' }
                },
                environment: {
                    DATABASE_URL: 'postgresql://postgres:postgres@db:5432/app',
                    REDIS_URL: 'redis://redis:6379/0',
                    SECRET_KEY: '${SECRET_KEY}'
                },
                networks: ['app-network'],
                restart: 'unless-stopped',
                healthcheck: {
                    test: ['CMD', 'curl', '-f', 'http://localhost:8000/health'],
                    interval: '30s', timeout: '10s', retries: 3, start_period: '30s'
                }
            },
            db: {
                image: 'postgres:15',
                volumes: ['db-data:/var/lib/postgresql/data'],
                environment: {
                    POSTGRES_DB: 'app',
                    POSTGRES_USER: 'postgres',
                    POSTGRES_PASSWORD: '${DB_PASSWORD}'
                },
                networks: ['app-network'],
                restart: 'unless-stopped',
                healthcheck: {
                    test: ['CMD-SHELL', 'pg_isready -U postgres'],
                    interval: '10s', timeout: '5s', retries: 5, start_period: '30s'
                }
            },
            redis: {
                image: 'redis:7-alpine',
                volumes: ['redis-data:/data'],
                networks: ['app-network'],
                restart: 'unless-stopped',
                healthcheck: {
                    test: ['CMD', 'redis-cli', 'ping'],
                    interval: '10s', timeout: '5s', retries: 5, start_period: '10s'
                }
            }
        },
        networks: { 'app-network': { driver: 'bridge' } },
        volumes: { 'db-data': {}, 'redis-data': {} }
    };
}
